def linear_search(arr: list, target) -> int:
    for i, val in enumerate(arr):
        if val == target:
            return i
    return -1

nums = [3, 1, 4, 1, 5, 9, 2, 6]
print(linear_search(nums, 5))   # 4
print(linear_search(nums, 7))   # -1

def binary_search(arr: list[int], target: int) -> int:
    lo, hi = 0, len(arr) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2   # avoids integer overflow vs (lo+hi)//2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

nums = [1, 3, 5, 7, 9, 11, 13, 15]
print(binary_search(nums, 7))   # 3
print(binary_search(nums, 6))   # -1

# Find the FIRST occurrence of target (left boundary)
def binary_search_left(arr: list[int], target: int) -> int:
    lo, hi = 0, len(arr) - 1
    result = -1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if arr[mid] == target:
            result = mid      # record this match...
            hi = mid - 1      # ...but keep searching left
        elif arr[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return result

nums = [1, 3, 3, 3, 5, 7]
print(binary_search_left(nums, 3))  # 1  (not 2 or 3)

# Two-sum on a sorted array — O(n) time, O(1) space
def two_sum_sorted(nums: list[int], target: int) -> tuple[int, int] | None:
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        s = nums[lo] + nums[hi]
        if s == target:
            return (lo, hi)
        elif s < target:
            lo += 1   # sum too small — move left pointer right
        else:
            hi -= 1   # sum too large — move right pointer left
    return None

print(two_sum_sorted([1, 2, 4, 6, 8, 11], 10))  # (2, 4) → 4+8

# Remove duplicates in place from sorted array — O(n) time, O(1) space
def remove_duplicates(nums: list[int]) -> int:
    if not nums:
        return 0
    slow = 0
    for fast in range(1, len(nums)):
        if nums[fast] != nums[slow]:
            slow += 1
            nums[slow] = nums[fast]
    return slow + 1  # new length

class ListNode:
    def __init__(self, val: int, next=None):
        self.val = val
        self.next = next

# Phase 1: detect whether a cycle exists
def has_cycle(head: ListNode | None) -> bool:
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            return True
    return False

# Phase 2: find the START of the cycle
def cycle_start(head: ListNode | None) -> ListNode | None:
    slow = fast = head
    while fast and fast.next:
        slow = slow.next
        fast = fast.next.next
        if slow is fast:
            # Reset one pointer to head; advance both at 1× speed
            slow = head
            while slow is not fast:
                slow = slow.next
                fast = fast.next
            return slow   # meeting point is the cycle entry
    return None

# Find the index of the maximum in a unimodal array
def ternary_search_max(arr: list[float]) -> int:
    lo, hi = 0, len(arr) - 1
    while hi - lo > 2:
        m1 = lo + (hi - lo) // 3
        m2 = hi - (hi - lo) // 3
        if arr[m1] < arr[m2]:
            lo = m1 + 1   # peak is in the right two-thirds
        else:
            hi = m2 - 1   # peak is in the left two-thirds
    return max(range(lo, hi + 1), key=lambda i: arr[i])

print(ternary_search_max([1, 3, 7, 9, 6, 2]))  # 3  (value 9)

def search_rotated(nums: list[int], target: int) -> int:
    lo, hi = 0, len(nums) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2
        if nums[mid] == target:
            return mid

        # Determine which half is sorted
        if nums[lo] <= nums[mid]:          # left half is sorted
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1              # target is in the sorted left half
            else:
                lo = mid + 1              # target must be in the right half
        else:                             # right half is sorted
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1              # target is in the sorted right half
            else:
                hi = mid - 1              # target must be in the left half
    return -1

print(search_rotated([4, 5, 6, 7, 0, 1, 2], 0))  # 4
print(search_rotated([4, 5, 6, 7, 0, 1, 2], 3))  # -1

# Problem 1: Find ANY peak element (element greater than its neighbors)
# Constraint: nums[-1] and nums[n] are treated as -∞
def find_peak(nums: list[int]) -> int:
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if nums[mid] > nums[mid + 1]:
            hi = mid          # peak is at mid or to the left
        else:
            lo = mid + 1      # mid+1 is higher, so a peak is to the right
    return lo

print(find_peak([1, 2, 3, 1]))        # 2  (value 3)
print(find_peak([1, 2, 1, 3, 5, 6, 4]))  # 5 or 1 — any peak is valid

# Problem 2: Find the minimum element in a rotated sorted array
def find_min_rotated(nums: list[int]) -> int:
    lo, hi = 0, len(nums) - 1
    while lo < hi:
        mid = lo + (hi - lo) // 2
        if nums[mid] > nums[hi]:
            lo = mid + 1      # min is in the right (unsorted) half
        else:
            hi = mid          # min is at mid or to the left
    return nums[lo]

print(find_min_rotated([4, 5, 6, 7, 0, 1, 2]))  # 0
